// Hearth & Hollow — ticket 54: pixel art for every ingredient and dish, drawn in code (FoodArtData.cs is
// generated by Tools/FoodArt/food_art.py). ArtLibrary falls back to these when its own slot is empty, so a
// hand-made sprite dropped into the Art Library still wins.
using System.Collections.Generic;
using HearthHollow.Core;
using HearthHollow.Data;
using UnityEngine;

namespace HearthHollow.UI
{
    public static partial class FoodArt
    {
        const float PPU = 16f;   // 16px sprites are one world unit
        static readonly Dictionary<string, Sprite> _cache = new Dictionary<string, Sprite>();
        static GameContent _content;

        /// Point ArtLibrary's ingredient / recipe lookups at the drawn art (GameBootstrap calls this).
        public static void Install(GameContent c)
        {
            _content = c;
            ArtLibrary.IngredientFallback = Ingredient;
            ArtLibrary.RecipeFallback = Recipe;
        }

        public static bool Has(string key) { return Data.ContainsKey(key); }
        public static int Count { get { return Data.Count; } }

        public static Sprite Ingredient(string id) { return string.IsNullOrEmpty(id) ? null : Get("ing:" + id); }

        /// A dish's picture; a dish without its own drawing gets its station's (bowl, skewer, sandwich).
        public static Sprite Recipe(string id)
        {
            if (string.IsNullOrEmpty(id)) return null;
            var s = Get("dish:" + id);
            if (s != null || _content == null) return s;
            var r = _content.recipes.Find(x => x.id == id);
            return r != null ? Get("station:" + r.station) : null;
        }

        public static Sprite Get(string key)
        {
            Sprite s;
            if (_cache.TryGetValue(key, out s) && s != null) return s;
            string[] d;
            if (!Data.TryGetValue(key, out d) || d.Length < 2) return null;
            var pal = new List<Color32>();
            foreach (var hex in d[0].Split(' '))
            {
                uint v = System.Convert.ToUInt32(hex, 16);
                pal.Add(new Color32((byte)(v >> 24), (byte)(v >> 16), (byte)(v >> 8), (byte)v));
            }
            int h = d.Length - 1, w = d[1].Length;
            var px = new Color32[w * h];
            for (int row = 0; row < h; row++)
            {
                string line = d[1 + row]; int y = h - 1 - row;   // data is top row first; textures start at the bottom
                for (int x = 0; x < w; x++)
                {
                    char ch = x < line.Length ? line[x] : '.';
                    int i = ch == '.' ? -1 : ch <= '9' ? ch - '0' : ch - 'a' + 10;
                    px[y * w + x] = i >= 0 && i < pal.Count ? pal[i] : new Color32(0, 0, 0, 0);
                }
            }
            var tex = new Texture2D(w, h, TextureFormat.RGBA32, false) { filterMode = FilterMode.Point, wrapMode = TextureWrapMode.Clamp, name = "food_" + key };
            tex.SetPixels32(px); tex.Apply();
            s = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f), PPU, 0, SpriteMeshType.FullRect);
            s.name = key;
            _cache[key] = s;
            return s;
        }
    }
}
